CREATE TABLE IF NOT EXISTS teams (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(100) NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS players (id INTEGER PRIMARY KEY AUTOINCREMENT, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, birth_date DATE NOT NULL, photo_path VARCHAR(255), team_id INTEGER NOT NULL REFERENCES teams(id) ON DELETE RESTRICT, shirt_number INTEGER, position VARCHAR(50), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS matchdays (id INTEGER PRIMARY KEY AUTOINCREMENT, number INTEGER NOT NULL UNIQUE, game_date DATE NOT NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS goals (id INTEGER PRIMARY KEY AUTOINCREMENT, player_id INTEGER NOT NULL REFERENCES players(id) ON DELETE RESTRICT, matchday_id INTEGER NOT NULL REFERENCES matchdays(id) ON DELETE RESTRICT, goals INTEGER NOT NULL CHECK(goals >= 0 AND goals <= 20), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(player_id,matchday_id));

CREATE TABLE IF NOT EXISTS incidents (id INTEGER PRIMARY KEY AUTOINCREMENT, player_id INTEGER NOT NULL REFERENCES players(id) ON DELETE RESTRICT, description VARCHAR(500) NOT NULL, card_type VARCHAR(10) NOT NULL CHECK(card_type IN ('yellow','red')), incident_date DATE NOT NULL, suspension_date DATE, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK((card_type = 'yellow' AND suspension_date IS NULL) OR (card_type = 'red' AND suspension_date IS NOT NULL AND suspension_date >= incident_date)));

CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(200) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('admin','referee')), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS login_attempts (fingerprint VARCHAR(64) PRIMARY KEY, failures INTEGER NOT NULL, last_failure INTEGER NOT NULL);

CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(30) PRIMARY KEY, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX idx_players_team_id ON players (team_id);

CREATE INDEX idx_incidents_player_id ON incidents (player_id);

CREATE INDEX idx_incidents_suspension_date ON incidents (suspension_date);

CREATE INDEX idx_goals_matchday_id ON goals (matchday_id);
